/// Input data for llama_encode/llama_decode A llama_batch object can contain
/// input about one or many sequences The provided arrays (i.e. token, embd,
/// pos, etc.) must have size of n_tokens
final class llama_batch extends ffi.Struct {
  @ffi.Int32()
  external int n_tokens;

  external ffi.Pointer<ffi.Int32> token;

  external ffi.Pointer<ffi.Float> embd;

  external ffi.Pointer<ffi.Int32> pos;

  external ffi.Pointer<ffi.Int32> n_seq_id;

  external ffi.Pointer<ffi.Pointer<ffi.Int32>> seq_id;

  /// TODO: rename this to "output"
  external ffi.Pointer<ffi.Int8> logits;

  static ffi.Pointer<llama_batch> $allocate(
    ffi.Allocator $allocator, {
    required int n_tokens,
    required ffi.Pointer<ffi.Int32> token,
    required ffi.Pointer<ffi.Float> embd,
    required ffi.Pointer<ffi.Int32> pos,
    required ffi.Pointer<ffi.Int32> n_seq_id,
    required ffi.Pointer<ffi.Pointer<ffi.Int32>> seq_id,
    required ffi.Pointer<ffi.Int8> logits,
  }) => $allocator<llama_batch>()
    ..ref.n_tokens = n_tokens
    ..ref.token = token
    ..ref.embd = embd
    ..ref.pos = pos
    ..ref.n_seq_id = n_seq_id
    ..ref.seq_id = seq_id
    ..ref.logits = logits;
}

final class llama_context extends ffi.Opaque {}

/// NOTE: changing the default values of parameters marked as [EXPERIMENTAL] may
/// cause crashes or incorrect results in certain configurations
/// https://github.com/ggml-org/llama.cpp/pull/7544
final class llama_context_params extends ffi.Struct {
  /// text context, 0 = from model
  @ffi.Uint32()
  external int n_ctx;

  /// logical maximum batch size that can be submitted to llama_decode
  @ffi.Uint32()
  external int n_batch;

  /// physical maximum batch size
  @ffi.Uint32()
  external int n_ubatch;

  /// max number of sequences (i.e. distinct states for recurrent models)
  @ffi.Uint32()
  external int n_seq_max;

  /// number of recurrent-state snapshots per seq for rollback (0 = no rollback)
  /// [EXPERIMENTAL]
  @ffi.Uint32()
  external int n_rs_seq;

  /// max outputs in a ubatch (0 = n_batch)
  @ffi.Uint32()
  external int n_outputs_max;

  /// max outputs per sequence (0 = n_outputs_max)
  @ffi.Uint32()
  external int n_outputs_max_per_seq;

  /// number of threads to use for generation
  @ffi.Int32()
  external int n_threads;

  /// number of threads to use for batch processing
  @ffi.Int32()
  external int n_threads_batch;

  /// set the context type (e.g. MTP)
  @ffi.UnsignedInt()
  external int ctx_typeAsInt;

  llama_context_type get ctx_type =>
      llama_context_type.fromValue(ctx_typeAsInt);
  set ctx_type(llama_context_type value) => ctx_typeAsInt = value.value;

  /// RoPE scaling type, from `enum llama_rope_scaling_type`
  @ffi.Int()
  external int rope_scaling_typeAsInt;

  llama_rope_scaling_type get rope_scaling_type =>
      llama_rope_scaling_type.fromValue(rope_scaling_typeAsInt);
  set rope_scaling_type(llama_rope_scaling_type value) =>
      rope_scaling_typeAsInt = value.value;

  /// whether to pool (sum) embedding results by sequence id
  @ffi.Int()
  external int pooling_typeAsInt;

  llama_pooling_type get pooling_type =>
      llama_pooling_type.fromValue(pooling_typeAsInt);
  set pooling_type(llama_pooling_type value) => pooling_typeAsInt = value.value;

  /// attention type to use for embeddings
  @ffi.Int()
  external int attention_typeAsInt;

  llama_attention_type get attention_type =>
      llama_attention_type.fromValue(attention_typeAsInt);
  set attention_type(llama_attention_type value) =>
      attention_typeAsInt = value.value;

  /// when to enable Flash Attention
  @ffi.Int()
  external int flash_attn_typeAsInt;

  llama_flash_attn_type get flash_attn_type =>
      llama_flash_attn_type.fromValue(flash_attn_typeAsInt);
  set flash_attn_type(llama_flash_attn_type value) =>
      flash_attn_typeAsInt = value.value;

  /// RoPE base frequency, 0 = from model
  @ffi.Float()
  external double rope_freq_base;

  /// RoPE frequency scaling factor, 0 = from model
  @ffi.Float()
  external double rope_freq_scale;

  /// YaRN extrapolation mix factor, negative = from model
  @ffi.Float()
  external double yarn_ext_factor;

  /// YaRN magnitude scaling factor
  @ffi.Float()
  external double yarn_attn_factor;

  /// YaRN low correction dim
  @ffi.Float()
  external double yarn_beta_fast;

  /// YaRN high correction dim
  @ffi.Float()
  external double yarn_beta_slow;

  /// YaRN original context size
  @ffi.Uint32()
  external int yarn_orig_ctx;

  /// [DEPRECATED] defragment the KV cache if holes/size > thold, <= 0 disabled
  /// (default)
  @ffi.Float()
  external double defrag_thold;

  external ffi.Pointer<
    ffi.NativeFunction<
      ffi.Bool Function(
        ffi.Pointer<ggml_tensor> t,
        ffi.Bool ask,
        ffi.Pointer<ffi.Void> user_data,
      )
    >
  >
  cb_eval;

  external ffi.Pointer<ffi.Void> cb_eval_user_data;

  /// data type for K cache [EXPERIMENTAL]
  @ffi.UnsignedInt()
  external int type_kAsInt;

  ggml_type get type_k => ggml_type.fromValue(type_kAsInt);
  set type_k(ggml_type value) => type_kAsInt = value.value;

  /// data type for V cache [EXPERIMENTAL]
  @ffi.UnsignedInt()
  external int type_vAsInt;

  ggml_type get type_v => ggml_type.fromValue(type_vAsInt);
  set type_v(ggml_type value) => type_vAsInt = value.value;

  /// device cache in bytes for the experts kept in host memory, split among the
  /// devices like the layers, 0 = disabled [EXPERIMENTAL]
  @ffi.Size()
  external int moe_cache_size;

  /// share of the MoE cache misses computed on the CPU instead of uploaded, 0 =
  /// all uploaded [EXPERIMENTAL]
  @ffi.Float()
  external double moe_cache_cpu_share;

  /// Abort callback if it returns true, execution of llama_decode() will be
  /// aborted currently works only with CPU execution
  external ffi.Pointer<
    ffi.NativeFunction<ffi.Bool Function(ffi.Pointer<ffi.Void> data)>
  >
  abort_callback;

  external ffi.Pointer<ffi.Void> abort_callback_data;

  /// if true, extract embeddings (together with logits, except for a pooling
  /// type other than NONE)
  @ffi.Bool()
  external bool embeddings;

  /// offload the KQV ops (including the KV cache) to GPU
  @ffi.Bool()
  external bool offload_kqv;

  /// measure performance timings
  @ffi.Bool()
  external bool no_perf;

  /// offload host tensor operations to device
  @ffi.Bool()
  external bool op_offload;

  /// use full-size SWA cache
  /// (https://github.com/ggml-org/llama.cpp/pull/13194#issuecomment-2868343055)
  /// NOTE: setting to false when n_seq_max > 1 can cause bad performance in
  /// some cases ref:
  /// https://github.com/ggml-org/llama.cpp/pull/13845#issuecomment-2924800573
  @ffi.Bool()
  external bool swa_full;

  /// use a unified buffer across the input sequences when computing the
  /// attention try to disable when n_seq_max > 1 for improved performance when
  /// the sequences do not share a large prefix ref:
  /// https://github.com/ggml-org/llama.cpp/pull/14363
  @ffi.Bool()
  external bool kv_unified;

  /// [EXPERIMENTAL] backend sampler chain configuration (make sure the caller
  /// keeps the sampler chains alive) note: the samplers must be sampler chains
  /// (i.e. use llama_sampler_chain_init)
  external ffi.Pointer<llama_sampler_seq_config> samplers;

  @ffi.Size()
  external int n_samplers;

  /// a source/target/parent context can be utilized in various ways, for
  /// example by sharing results or llama_memory between 2 contexts
  external ffi.Pointer<llama_context> ctx_other;

  static ffi.Pointer<llama_context_params> $allocate(
    ffi.Allocator $allocator, {
    required int n_ctx,
    required int n_batch,
    required int n_ubatch,
    required int n_seq_max,
    required int n_rs_seq,
    required int n_outputs_max,
    required int n_outputs_max_per_seq,
    required int n_threads,
    required int n_threads_batch,
    required llama_context_type ctx_type,
    required llama_rope_scaling_type rope_scaling_type,
    required llama_pooling_type pooling_type,
    required llama_attention_type attention_type,
    required llama_flash_attn_type flash_attn_type,
    required double rope_freq_base,
    required double rope_freq_scale,
    required double yarn_ext_factor,
    required double yarn_attn_factor,
    required double yarn_beta_fast,
    required double yarn_beta_slow,
    required int yarn_orig_ctx,
    required double defrag_thold,
    required ffi.Pointer<
      ffi.NativeFunction<
        ffi.Bool Function(
          ffi.Pointer<ggml_tensor> t,
          ffi.Bool ask,
          ffi.Pointer<ffi.Void> user_data,
        )
      >
    >
    cb_eval,
    required ffi.Pointer<ffi.Void> cb_eval_user_data,
    required ggml_type type_k,
    required ggml_type type_v,
    required int moe_cache_size,
    required double moe_cache_cpu_share,
    required ffi.Pointer<
      ffi.NativeFunction<ffi.Bool Function(ffi.Pointer<ffi.Void> data)>
    >
    abort_callback,
    required ffi.Pointer<ffi.Void> abort_callback_data,
    required bool embeddings,
    required bool offload_kqv,
    required bool no_perf,
    required bool op_offload,
    required bool swa_full,
    required bool kv_unified,
    required ffi.Pointer<llama_sampler_seq_config> samplers,
    required int n_samplers,
    required ffi.Pointer<llama_context> ctx_other,
  }) => $allocator<llama_context_params>()
    ..ref.n_ctx = n_ctx
    ..ref.n_batch = n_batch
    ..ref.n_ubatch = n_ubatch
    ..ref.n_seq_max = n_seq_max
    ..ref.n_rs_seq = n_rs_seq
    ..ref.n_outputs_max = n_outputs_max
    ..ref.n_outputs_max_per_seq = n_outputs_max_per_seq
    ..ref.n_threads = n_threads
    ..ref.n_threads_batch = n_threads_batch
    ..ref.ctx_type = ctx_type
    ..ref.rope_scaling_type = rope_scaling_type
    ..ref.pooling_type = pooling_type
    ..ref.attention_type = attention_type
    ..ref.flash_attn_type = flash_attn_type
    ..ref.rope_freq_base = rope_freq_base
    ..ref.rope_freq_scale = rope_freq_scale
    ..ref.yarn_ext_factor = yarn_ext_factor
    ..ref.yarn_attn_factor = yarn_attn_factor
    ..ref.yarn_beta_fast = yarn_beta_fast
    ..ref.yarn_beta_slow = yarn_beta_slow
    ..ref.yarn_orig_ctx = yarn_orig_ctx
    ..ref.defrag_thold = defrag_thold
    ..ref.cb_eval = cb_eval
    ..ref.cb_eval_user_data = cb_eval_user_data
    ..ref.type_k = type_k
    ..ref.type_v = type_v
    ..ref.moe_cache_size = moe_cache_size
    ..ref.moe_cache_cpu_share = moe_cache_cpu_share
    ..ref.abort_callback = abort_callback
    ..ref.abort_callback_data = abort_callback_data
    ..ref.embeddings = embeddings
    ..ref.offload_kqv = offload_kqv
    ..ref.no_perf = no_perf
    ..ref.op_offload = op_offload
    ..ref.swa_full = swa_full
    ..ref.kv_unified = kv_unified
    ..ref.samplers = samplers
    ..ref.n_samplers = n_samplers
    ..ref.ctx_other = ctx_other;
}

enum llama_context_type {
  LLAMA_CONTEXT_TYPE_DEFAULT(0),
  LLAMA_CONTEXT_TYPE_MTP(1);

  final int value;
  const llama_context_type(this.value);

  static llama_context_type fromValue(int value) => switch (value) {
    0 => LLAMA_CONTEXT_TYPE_DEFAULT,
    1 => LLAMA_CONTEXT_TYPE_MTP,
    _ => throw ArgumentError('Unknown value for llama_context_type: $value'),
  };
}

enum llama_flash_attn_type {
  LLAMA_FLASH_ATTN_TYPE_AUTO(-1),
  LLAMA_FLASH_ATTN_TYPE_DISABLED(0),
  LLAMA_FLASH_ATTN_TYPE_ENABLED(1);

  final int value;
  const llama_flash_attn_type(this.value);

  static llama_flash_attn_type fromValue(int value) => switch (value) {
    -1 => LLAMA_FLASH_ATTN_TYPE_AUTO,
    0 => LLAMA_FLASH_ATTN_TYPE_DISABLED,
    1 => LLAMA_FLASH_ATTN_TYPE_ENABLED,
    _ => throw ArgumentError('Unknown value for llama_flash_attn_type: $value'),
  };
}

enum llama_lazy_mode {
  /// always read the whole tensor up front
  LLAMA_LAZY_MODE_OFF(0),

  /// lazy only for marked tensors larger than 4 GiB (requires mmap)
  LLAMA_LAZY_MODE_AUTO(1),

  /// read the rows of tensors marked by the arch on demand (requires mmap)
  LLAMA_LAZY_MODE_ON(2);

  final int value;
  const llama_lazy_mode(this.value);

  static llama_lazy_mode fromValue(int value) => switch (value) {
    0 => LLAMA_LAZY_MODE_OFF,
    1 => LLAMA_LAZY_MODE_AUTO,
    2 => LLAMA_LAZY_MODE_ON,
    _ => throw ArgumentError('Unknown value for llama_lazy_mode: $value'),
  };
}

enum llama_load_mode {
  /// auto-detect based on device capabilities
  LLAMA_LOAD_MODE_AUTO(-1),

  /// no special loading mode
  LLAMA_LOAD_MODE_NONE(0),

  /// memory map the model
  LLAMA_LOAD_MODE_MMAP(1),

  /// force system to keep model in RAM rather than swapping or compressing
  LLAMA_LOAD_MODE_MLOCK(2),

  /// mmap + force system to keep model in RAM rather than swapping or
  /// compressing
  LLAMA_LOAD_MODE_MMAP_MLOCK(3),

  /// use direct I/O if available
  LLAMA_LOAD_MODE_DIRECT_IO(4);

  final int value;
  const llama_load_mode(this.value);

  static llama_load_mode fromValue(int value) => switch (value) {
    -1 => LLAMA_LOAD_MODE_AUTO,
    0 => LLAMA_LOAD_MODE_NONE,
    1 => LLAMA_LOAD_MODE_MMAP,
    2 => LLAMA_LOAD_MODE_MLOCK,
    3 => LLAMA_LOAD_MODE_MMAP_MLOCK,
    4 => LLAMA_LOAD_MODE_DIRECT_IO,
    _ => throw ArgumentError('Unknown value for llama_load_mode: $value'),
  };
}

final class llama_memory_i extends ffi.Opaque {}

final class llama_model extends ffi.Opaque {}

final class llama_model_kv_override extends ffi.Opaque {}

final class llama_model_params extends ffi.Struct {
  /// NULL-terminated list of devices to use for offloading (if NULL, all
  /// available devices are used)
  external ffi.Pointer<ffi.Pointer<ggml_backend_device>> devices;

  /// NULL-terminated list of buffer types to use for tensors that match a
  /// pattern
  external ffi.Pointer<llama_model_tensor_buft_override> tensor_buft_overrides;

  /// number of layers to store in VRAM, a negative value means all layers
  @ffi.Int32()
  external int n_gpu_layers;

  /// how to split the model across multiple GPUs
  @ffi.UnsignedInt()
  external int split_modeAsInt;

  llama_split_mode get split_mode =>
      llama_split_mode.fromValue(split_modeAsInt);
  set split_mode(llama_split_mode value) => split_modeAsInt = value.value;

  /// how to load the model
  @ffi.Int()
  external int load_modeAsInt;

  llama_load_mode get load_mode => llama_load_mode.fromValue(load_modeAsInt);
  set load_mode(llama_load_mode value) => load_modeAsInt = value.value;

  /// on-demand reading of tensors marked by the arch
  @ffi.UnsignedInt()
  external int lazy_modeAsInt;

  llama_lazy_mode get lazy_mode => llama_lazy_mode.fromValue(lazy_modeAsInt);
  set lazy_mode(llama_lazy_mode value) => lazy_modeAsInt = value.value;

  /// the GPU that is used for the entire model when split_mode is
  /// LLAMA_SPLIT_MODE_NONE
  @ffi.Int32()
  external int main_gpu;

  /// proportion of the model (layers or rows) to offload to each GPU, size:
  /// llama_max_devices()
  external ffi.Pointer<ffi.Float> tensor_split;

  /// Called with a progress value between 0.0 and 1.0. Pass NULL to disable. If
  /// the provided progress_callback returns true, model loading continues. If
  /// it returns false, model loading is immediately aborted.
  external ffi.Pointer<
    ffi.NativeFunction<
      ffi.Bool Function(ffi.Float progress, ffi.Pointer<ffi.Void> user_data)
    >
  >
  progress_callback;

  /// context pointer passed to the progress callback
  external ffi.Pointer<ffi.Void> progress_callback_user_data;

  /// override key-value pairs of the model meta data
  external ffi.Pointer<llama_model_kv_override> kv_overrides;

  /// only load the vocabulary, no weights
  @ffi.Bool()
  external bool vocab_only;

  /// validate model tensor data
  @ffi.Bool()
  external bool check_tensors;

  /// use extra buffer types (used for weight repacking)
  @ffi.Bool()
  external bool use_extra_bufts;

  /// bypass host buffer allowing extra buffers to be used
  @ffi.Bool()
  external bool no_host;

  /// only load metadata and simulate memory allocations
  @ffi.Bool()
  external bool no_alloc;

  /// whether to load MTP layers
  @ffi.Bool()
  external bool load_mtp;

  static ffi.Pointer<llama_model_params> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<ffi.Pointer<ggml_backend_device>> devices,
    required ffi.Pointer<llama_model_tensor_buft_override>
    tensor_buft_overrides,
    required int n_gpu_layers,
    required llama_split_mode split_mode,
    required llama_load_mode load_mode,
    required llama_lazy_mode lazy_mode,
    required int main_gpu,
    required ffi.Pointer<ffi.Float> tensor_split,
    required ffi.Pointer<
      ffi.NativeFunction<
        ffi.Bool Function(ffi.Float progress, ffi.Pointer<ffi.Void> user_data)
      >
    >
    progress_callback,
    required ffi.Pointer<ffi.Void> progress_callback_user_data,
    required ffi.Pointer<llama_model_kv_override> kv_overrides,
    required bool vocab_only,
    required bool check_tensors,
    required bool use_extra_bufts,
    required bool no_host,
    required bool no_alloc,
    required bool load_mtp,
  }) => $allocator<llama_model_params>()
    ..ref.devices = devices
    ..ref.tensor_buft_overrides = tensor_buft_overrides
    ..ref.n_gpu_layers = n_gpu_layers
    ..ref.split_mode = split_mode
    ..ref.load_mode = load_mode
    ..ref.lazy_mode = lazy_mode
    ..ref.main_gpu = main_gpu
    ..ref.tensor_split = tensor_split
    ..ref.progress_callback = progress_callback
    ..ref.progress_callback_user_data = progress_callback_user_data
    ..ref.kv_overrides = kv_overrides
    ..ref.vocab_only = vocab_only
    ..ref.check_tensors = check_tensors
    ..ref.use_extra_bufts = use_extra_bufts
    ..ref.no_host = no_host
    ..ref.no_alloc = no_alloc
    ..ref.load_mtp = load_mtp;
}

final class llama_model_tensor_buft_override extends ffi.Opaque {}

enum llama_pooling_type {
  LLAMA_POOLING_TYPE_UNSPECIFIED(-1),
  LLAMA_POOLING_TYPE_NONE(0),
  LLAMA_POOLING_TYPE_MEAN(1),
  LLAMA_POOLING_TYPE_CLS(2),
  LLAMA_POOLING_TYPE_LAST(3),

  /// used by reranking models to attach the classification head to the graph
  LLAMA_POOLING_TYPE_RANK(4);

  final int value;
  const llama_pooling_type(this.value);

  static llama_pooling_type fromValue(int value) => switch (value) {
    -1 => LLAMA_POOLING_TYPE_UNSPECIFIED,
    0 => LLAMA_POOLING_TYPE_NONE,
    1 => LLAMA_POOLING_TYPE_MEAN,
    2 => LLAMA_POOLING_TYPE_CLS,
    3 => LLAMA_POOLING_TYPE_LAST,
    4 => LLAMA_POOLING_TYPE_RANK,
    _ => throw ArgumentError('Unknown value for llama_pooling_type: $value'),
  };
}

enum llama_rope_scaling_type {
  LLAMA_ROPE_SCALING_TYPE_UNSPECIFIED(-1),
  LLAMA_ROPE_SCALING_TYPE_NONE(0),
  LLAMA_ROPE_SCALING_TYPE_LINEAR(1),
  LLAMA_ROPE_SCALING_TYPE_YARN(2),
  LLAMA_ROPE_SCALING_TYPE_LONGROPE(3);

  static const LLAMA_ROPE_SCALING_TYPE_MAX_VALUE =
      LLAMA_ROPE_SCALING_TYPE_LONGROPE;

  final int value;
  const llama_rope_scaling_type(this.value);

  static llama_rope_scaling_type fromValue(int value) => switch (value) {
    -1 => LLAMA_ROPE_SCALING_TYPE_UNSPECIFIED,
    0 => LLAMA_ROPE_SCALING_TYPE_NONE,
    1 => LLAMA_ROPE_SCALING_TYPE_LINEAR,
    2 => LLAMA_ROPE_SCALING_TYPE_YARN,
    3 => LLAMA_ROPE_SCALING_TYPE_LONGROPE,
    _ => throw ArgumentError(
      'Unknown value for llama_rope_scaling_type: $value',
    ),
  };

  @override
  String toString() {
    if (this == LLAMA_ROPE_SCALING_TYPE_LONGROPE)
      return "llama_rope_scaling_type.LLAMA_ROPE_SCALING_TYPE_LONGROPE, llama_rope_scaling_type.LLAMA_ROPE_SCALING_TYPE_MAX_VALUE";
    return super.toString();
  }
}

final class llama_sampler extends ffi.Opaque {}

final class llama_sampler_chain_params extends ffi.Struct {
  /// whether to measure performance timings
  @ffi.Bool()
  external bool no_perf;

  static ffi.Pointer<llama_sampler_chain_params> $allocate(
    ffi.Allocator $allocator, {
    required bool no_perf,
  }) => $allocator<llama_sampler_chain_params>()..ref.no_perf = no_perf;
}

final class llama_sampler_seq_config extends ffi.Opaque {}

enum llama_split_mode {
  /// single GPU
  LLAMA_SPLIT_MODE_NONE(0),

  /// split layers and KV across GPUs
  LLAMA_SPLIT_MODE_LAYER(1),

  /// split layers and KV across GPUs, use tensor parallelism if supported
  LLAMA_SPLIT_MODE_ROW(2),
  LLAMA_SPLIT_MODE_TENSOR(3);

  final int value;
  const llama_split_mode(this.value);

  static llama_split_mode fromValue(int value) => switch (value) {
    0 => LLAMA_SPLIT_MODE_NONE,
    1 => LLAMA_SPLIT_MODE_LAYER,
    2 => LLAMA_SPLIT_MODE_ROW,
    3 => LLAMA_SPLIT_MODE_TENSOR,
    _ => throw ArgumentError('Unknown value for llama_split_mode: $value'),
  };
}

